#include <stdlib.h>
#include <string.h>
#if defined(__AVX512F__) || defined(__AVX2__)
#include <immintrin.h>
#endif

#define KC 256
#define NC 256
#define MC 48

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#define DECL(r) __m512 c##r##_0, c##r##_1;
#define ZERO(r) c##r##_0 = _mm512_setzero_ps(); c##r##_1 = _mm512_setzero_ps();
#define LOAD(r) c##r##_0 = _mm512_loadu_ps(C + (r) * ldc); \
                c##r##_1 = _mm512_loadu_ps(C + (r) * ldc + 16);
#define FMA(r) { __m512 a = _mm512_set1_ps(A[(r) * lda]); \
                 c##r##_0 = _mm512_fmadd_ps(a, b0, c##r##_0); \
                 c##r##_1 = _mm512_fmadd_ps(a, b1, c##r##_1); }
#define STORE(r) _mm512_storeu_ps(C + (r) * ldc, c##r##_0); \
                 _mm512_storeu_ps(C + (r) * ldc + 16, c##r##_1);
#define ALL(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)

static void kern(const float *restrict A, long lda, const float *restrict B,
                 int kc, float *restrict C, long ldc, int first)
{
    ALL(DECL)
    if (first) { ALL(ZERO) } else { ALL(LOAD) }
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(B);
        __m512 b1 = _mm512_load_ps(B + 16);
        ALL(FMA)
        B += NR;
        A++;
    }
    ALL(STORE)
}

#elif defined(__AVX2__) && defined(__FMA__)
#define MR 6
#define NR 16
#define DECL(r) __m256 c##r##_0, c##r##_1;
#define ZERO(r) c##r##_0 = _mm256_setzero_ps(); c##r##_1 = _mm256_setzero_ps();
#define LOAD(r) c##r##_0 = _mm256_loadu_ps(C + (r) * ldc); \
                c##r##_1 = _mm256_loadu_ps(C + (r) * ldc + 8);
#define FMA(r) { __m256 a = _mm256_broadcast_ss(A + (r) * lda); \
                 c##r##_0 = _mm256_fmadd_ps(a, b0, c##r##_0); \
                 c##r##_1 = _mm256_fmadd_ps(a, b1, c##r##_1); }
#define STORE(r) _mm256_storeu_ps(C + (r) * ldc, c##r##_0); \
                 _mm256_storeu_ps(C + (r) * ldc + 8, c##r##_1);
#define ALL(X) X(0) X(1) X(2) X(3) X(4) X(5)

static void kern(const float *restrict A, long lda, const float *restrict B,
                 int kc, float *restrict C, long ldc, int first)
{
    ALL(DECL)
    if (first) { ALL(ZERO) } else { ALL(LOAD) }
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(B);
        __m256 b1 = _mm256_load_ps(B + 8);
        ALL(FMA)
        B += NR;
        A++;
    }
    ALL(STORE)
}

#else
#define MR 4
#define NR 16
static void kern(const float *restrict A, long lda, const float *restrict B,
                 int kc, float *restrict C, long ldc, int first)
{
    float c[MR][NR];
    for (int r = 0; r < MR; r++)
        for (int j = 0; j < NR; j++)
            c[r][j] = first ? 0.0f : C[r * ldc + j];
    for (int k = 0; k < kc; k++) {
        const float *b = B + (long)k * NR;
        for (int r = 0; r < MR; r++) {
            float a = A[r * lda + k];
            for (int j = 0; j < NR; j++)
                c[r][j] += a * b[j];
        }
    }
    for (int r = 0; r < MR; r++)
        for (int j = 0; j < NR; j++)
            C[r * ldc + j] = c[r][j];
}
#endif

static float *bp_buf = NULL;
static size_t bp_cap = 0;

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    const long N = n;
    const int njp = (n + NR - 1) / NR;
    const long npad = (long)njp * NR;
    const int nkb = (n + KC - 1) / KC;

    size_t need = (size_t)N * npad * sizeof(float);
    need = (need + 63) & ~(size_t)63;
    if (need > bp_cap) {
        free(bp_buf);
        bp_buf = (float *)aligned_alloc(64, need);
        bp_cap = need;
    }
    float *Bp = bp_buf;

    const int nib = (n + MC - 1) / MC;
    const int njc = (int)((npad + NC - 1) / NC);
    const int ntask = nib * njc;
    const int alias = (n % 512) == 0;

#pragma omp parallel
    {
        float ebuf[MR * KC] __attribute__((aligned(64)));
        float ctmp[MR * NR] __attribute__((aligned(64)));

        /* Pack B: panel (kb, jp) holds kc rows of NR contiguous columns,
           zero-padded past column n. */
#pragma omp for schedule(static)
        for (int p = 0; p < nkb * njp; p++) {
            int q = p / njp, jp = p % njp;
            long k0 = (long)q * KC;
            int kc = (int)(N - k0 < KC ? N - k0 : KC);
            long j0 = (long)jp * NR;
            float *dst = Bp + k0 * npad + j0 * kc;
            int nv = (int)(N - j0 < NR ? N - j0 : NR);
            for (int k = 0; k < kc; k++) {
                const float *src = B + (k0 + k) * N + j0;
                float *d = dst + (long)k * NR;
                int j = 0;
                for (; j < nv; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }

#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntask; t++) {
            int ib = t / njc, jc = t % njc;
            long i0 = (long)ib * MC;
            long i1 = i0 + MC < N ? i0 + MC : N;
            long jcs = (long)jc * NC;
            long jce = jcs + NC < npad ? jcs + NC : npad;

            for (long k0 = 0; k0 < N; k0 += KC) {
                int kc = (int)(N - k0 < KC ? N - k0 : KC);
                int first = (k0 == 0);
                const float *Bk = Bp + k0 * npad;

                for (long i = i0; i < i1; i += MR) {
                    int mr = (int)(i1 - i < MR ? i1 - i : MR);
                    const float *Ap;
                    long lda;
                    if (mr < MR || alias) {
                        for (int r = 0; r < MR; r++) {
                            if (r < mr)
                                memcpy(ebuf + r * kc, A + (i + r) * N + k0,
                                       (size_t)kc * sizeof(float));
                            else
                                memset(ebuf + r * kc, 0,
                                       (size_t)kc * sizeof(float));
                        }
                        Ap = ebuf;
                        lda = kc;
                    } else {
                        Ap = A + i * N + k0;
                        lda = N;
                    }

                    for (long j = jcs; j < jce; j += NR) {
                        int nr = (int)(N - j < NR ? N - j : NR);
                        const float *Bpp = Bk + j * kc;
                        float *Cij = C + i * N + j;
                        if (mr == MR && nr == NR) {
                            kern(Ap, lda, Bpp, kc, Cij, N, first);
                        } else {
                            if (!first)
                                for (int r = 0; r < mr; r++)
                                    memcpy(ctmp + r * NR, Cij + r * N,
                                           (size_t)nr * sizeof(float));
                            kern(Ap, lda, Bpp, kc, ctmp, NR, first);
                            for (int r = 0; r < mr; r++)
                                memcpy(Cij + r * N, ctmp + r * NR,
                                       (size_t)nr * sizeof(float));
                        }
                    }
                }
            }
        }
    }
}
